## Manifest 完整接口定义

以下 JSON 与插件包内实际 `manifest.json` 逐字段一致，覆盖插件身份、权限、配置、鉴权、参数、校验、创建、Agent、查询、取消、结果下载、响应和 Agent 响应映射。`documentation` 字段的值就是当前完整文档；为避免文档在自身内部无限递归，JSON 中仅用等义占位文本表示正文。

```json
{
  "apiVersion": "qisitv.plugin/v2",
  "id": "luma-dream-machine",
  "name": "Luma Dream Machine",
  "version": "2.0.1",
  "author": "BeefTV Contributors",
  "description": "Luma Dream Machine 独立请求协议插件。",
  "documentation": "<当前插件的完整 documentation，由 README.md 与 docs/interface.md 拼接而成；为避免 JSON 递归，此处不重复展开正文。>",
  "permissions": [
    "generation.run",
    "media.read"
  ],
  "configuration": {
    "fields": [
      {
        "name": "apiKey",
        "type": "secret",
        "label": "API Key",
        "required": true
      }
    ]
  },
  "contributes": {
    "providers": [
      {
        "id": "luma-dream-machine",
        "label": "Luma Dream Machine",
        "capabilities": [
          "video"
        ],
        "scopes": [
          "admin.system-channel",
          "user.custom-channel",
          "canvas",
          "creation",
          "agent"
        ],
        "baseUrl": "https://api.lumalabs.ai",
        "requiresPublicMediaUrls": true,
        "mediaTransport": {
          "image": "url"
        },
        "auth": {
          "type": "bearer",
          "field": "apiKey"
        },
        "parameters": [
          {
            "name": "model",
            "type": "string",
            "required": true,
            "mapping": "model",
            "description": "视频模型 ID。"
          },
          {
            "name": "prompt",
            "type": "string",
            "required": true,
            "mapping": "prompt",
            "description": "视频提示词。"
          },
          {
            "name": "images",
            "type": "media[]",
            "required": false,
            "mapping": "keyframes.frame0 / frame1",
            "description": "首帧与尾帧；官方服务建议传公网图片地址。"
          },
          {
            "name": "duration",
            "type": "integer",
            "required": false,
            "mapping": "duration（如 5s）",
            "description": "时长秒数，按官方字符串格式发送。"
          },
          {
            "name": "aspectRatio",
            "type": "string",
            "required": false,
            "mapping": "aspect_ratio",
            "description": "画幅比例。"
          },
          {
            "name": "resolution",
            "type": "string",
            "required": false,
            "mapping": "resolution",
            "description": "分辨率档位，小写后发送，2160p 按官方写法转成 4k。"
          },
          {
            "name": "providerOptions",
            "type": "object",
            "required": false,
            "mapping": "provider-specific fields",
            "description": "插件命名空间内的厂商扩展字段。"
          }
        ],
        "create": {
          "method": "POST",
          "path": "/dream-machine/v1/generations",
          "originPath": true,
          "contentType": "application/json",
          "body": {
            "$merge": [
              {
                "model": {
                  "$ref": "request.model"
                },
                "prompt": {
                  "$ref": "request.prompt"
                },
                "aspect_ratio": {
                  "$omitEmpty": {
                    "$if": {
                      "condition": {
                        "$in": [
                          {
                            "$lower": {
                              "$trim": {
                                "$ref": "request.aspectRatio"
                              }
                            }
                          },
                          [
                            "",
                            "auto"
                          ]
                        ]
                      },
                      "then": null,
                      "else": {
                        "$trim": {
                          "$ref": "request.aspectRatio"
                        }
                      }
                    }
                  }
                },
                "resolution": {
                  "$omitEmpty": {
                    "$switch": {
                      "cases": [
                        {
                          "when": {
                            "$in": [
                              {
                                "$lower": {
                                  "$trim": {
                                    "$ref": "request.resolution"
                                  }
                                }
                              },
                              [
                                "2160p",
                                "4k",
                                "2160"
                              ]
                            ]
                          },
                          "then": "4k"
                        }
                      ],
                      "default": {
                        "$lower": {
                          "$trim": {
                            "$ref": "request.resolution"
                          }
                        }
                      }
                    }
                  }
                },
                "duration": {
                  "$omitEmpty": {
                    "$if": {
                      "condition": {
                        "$gt": [
                          {
                            "$ref": "request.duration"
                          },
                          0
                        ]
                      },
                      "then": {
                        "$concat": [
                          {
                            "$ref": "request.duration"
                          },
                          "s"
                        ]
                      },
                      "else": null
                    }
                  }
                },
                "keyframes": {
                  "$if": {
                    "condition": {
                      "$gt": [
                        {
                          "$len": {
                            "$coalesce": [
                              {
                                "$ref": "request.images"
                              },
                              []
                            ]
                          }
                        },
                        0
                      ]
                    },
                    "then": {
                      "$merge": [
                        {
                          "frame0": {
                            "$if": {
                              "condition": {
                                "$gt": [
                                  {
                                    "$len": {
                                      "$filter": {
                                        "from": {
                                          "$sortByOrder": {
                                            "$ref": "request.images"
                                          }
                                        },
                                        "as": "media",
                                        "where": {
                                          "$in": [
                                            {
                                              "$ref": "media.role"
                                            },
                                            [
                                              "first_frame",
                                              ""
                                            ]
                                          ]
                                        }
                                      }
                                    }
                                  },
                                  0
                                ]
                              },
                              "then": {
                                "type": "image",
                                "url": {
                                  "$first": {
                                    "$map": {
                                      "from": {
                                        "$filter": {
                                          "from": {
                                            "$sortByOrder": {
                                              "$ref": "request.images"
                                            }
                                          },
                                          "as": "media",
                                          "where": {
                                            "$in": [
                                              {
                                                "$ref": "media.role"
                                              },
                                              [
                                                "first_frame",
                                                ""
                                              ]
                                            ]
                                          }
                                        }
                                      },
                                      "as": "media",
                                      "in": {
                                        "$ref": "media.value"
                                      }
                                    }
                                  }
                                }
                              },
                              "else": null
                            }
                          }
                        },
                        {
                          "frame1": {
                            "$if": {
                              "condition": {
                                "$gt": [
                                  {
                                    "$len": {
                                      "$filter": {
                                        "from": {
                                          "$sortByOrder": {
                                            "$ref": "request.images"
                                          }
                                        },
                                        "as": "media",
                                        "where": {
                                          "$in": [
                                            {
                                              "$ref": "media.role"
                                            },
                                            [
                                              "last_frame"
                                            ]
                                          ]
                                        }
                                      }
                                    }
                                  },
                                  0
                                ]
                              },
                              "then": {
                                "type": "image",
                                "url": {
                                  "$first": {
                                    "$map": {
                                      "from": {
                                        "$filter": {
                                          "from": {
                                            "$sortByOrder": {
                                              "$ref": "request.images"
                                            }
                                          },
                                          "as": "media",
                                          "where": {
                                            "$in": [
                                              {
                                                "$ref": "media.role"
                                              },
                                              [
                                                "last_frame"
                                              ]
                                            ]
                                          }
                                        }
                                      },
                                      "as": "media",
                                      "in": {
                                        "$ref": "media.value"
                                      }
                                    }
                                  }
                                }
                              },
                              "else": null
                            }
                          }
                        }
                      ]
                    },
                    "else": null
                  }
                }
              },
              {
                "$coalesce": [
                  {
                    "$ref": "request.providerOptions.luma-dream-machine.body"
                  },
                  {
                    "$ref": "request.providerOptions.luma-dream-machine.extra_body"
                  },
                  {}
                ]
              }
            ]
          }
        },
        "poll": {
          "method": "GET",
          "path": "/dream-machine/v1/generations/{{taskId}}",
          "originPath": true
        },
        "response": {
          "taskId": {
            "$coalesce": [
              {
                "$ref": "response.id"
              },
              {
                "$ref": "response.task_id"
              },
              {
                "$ref": "response.taskId"
              },
              {
                "$ref": "response.data.id"
              },
              {
                "$ref": "taskId"
              }
            ]
          },
          "status": {
            "$if": {
              "condition": {
                "$eq": [
                  {
                    "$lower": {
                      "$trim": {
                        "$ref": "response.state"
                      }
                    }
                  },
                  "dreaming"
                ]
              },
              "then": "processing",
              "else": {
                "$coalesce": [
                  {
                    "$ref": "response.state"
                  },
                  {
                    "$ref": "response.status"
                  },
                  {
                    "$ref": "response.data.status"
                  },
                  "pending"
                ]
              }
            }
          },
          "message": {
            "$coalesce": [
              {
                "$ref": "response.failure_reason"
              },
              {
                "$ref": "response.error.message"
              },
              {
                "$ref": "response.message"
              },
              {
                "$ref": "response.fail_reason"
              }
            ]
          },
          "videos": {
            "$coalesce": [
              {
                "$ref": "response.assets.video"
              },
              {
                "$ref": "response.video_url"
              },
              {
                "$ref": "response.videoUrl"
              },
              {
                "$ref": "response.result_url"
              },
              {
                "$ref": "response.url"
              },
              {
                "$ref": "response.data.video_url"
              },
              {
                "$ref": "response.output.url"
              }
            ]
          },
          "errorPaths": [
            "error.code"
          ],
          "resultEphemeral": true
        },
        "validations": [
          {
            "assert": {
              "$eq": [
                {
                  "$len": {
                    "$filter": {
                      "from": {
                        "$ref": "request.images"
                      },
                      "as": "media",
                      "where": {
                        "$in": [
                          {
                            "$ref": "media.role"
                          },
                          [
                            "reference_image",
                            "subject_reference",
                            "style_reference"
                          ]
                        ]
                      }
                    }
                  }
                },
                0
              ]
            },
            "message": "Luma Dream Machine 当前 profile 只发送首帧和尾帧，角色或风格参考图请改用支持参考图的协议"
          },
          {
            "assert": {
              "$lte": [
                {
                  "$len": {
                    "$filter": {
                      "from": {
                        "$ref": "request.images"
                      },
                      "as": "media",
                      "where": {
                        "$in": [
                          {
                            "$ref": "media.role"
                          },
                          [
                            "first_frame",
                            ""
                          ]
                        ]
                      }
                    }
                  }
                },
                1
              ]
            },
            "message": "Luma Dream Machine 最多接收一张首帧图片"
          },
          {
            "assert": {
              "$lte": [
                {
                  "$len": {
                    "$filter": {
                      "from": {
                        "$ref": "request.images"
                      },
                      "as": "media",
                      "where": {
                        "$in": [
                          {
                            "$ref": "media.role"
                          },
                          [
                            "last_frame"
                          ]
                        ]
                      }
                    }
                  }
                },
                1
              ]
            },
            "message": "Luma Dream Machine 最多接收一张尾帧图片"
          },
          {
            "assert": {
              "$eq": [
                {
                  "$len": {
                    "$coalesce": [
                      {
                        "$ref": "request.videos"
                      },
                      []
                    ]
                  }
                },
                0
              ]
            },
            "message": "Luma Dream Machine 当前 profile 不发送参考视频，请改用支持参考视频的协议"
          },
          {
            "assert": {
              "$eq": [
                {
                  "$len": {
                    "$coalesce": [
                      {
                        "$ref": "request.audios"
                      },
                      []
                    ]
                  }
                },
                0
              ]
            },
            "message": "Luma Dream Machine 当前 profile 不发送参考音频，请改用支持参考音频的协议"
          }
        ]
      }
    ]
  }
}
```
